SET @canal_balcao = (SELECT id FROM salesChannels WHERE code = 'BALCAO' LIMIT 1);

INSERT INTO products (name, categoryId, subcategory, ean, uom, minStock, currentStock, avgCost, active, isComposite, notes, createdAt, updatedAt)
VALUES 
('Heineken 269ml', @categoria_bebidas, 'Cerveja Premium', '7891991010924', 'UN', 24, 100, '3.50', 1, 0, 'Cerveja importada premium', NOW(), NOW());

SET @heineken_unit_id = LAST_INSERT_ID();

INSERT INTO productPrices (productId, channelId, price, effectiveFrom, createdAt, updatedAt)
VALUES (@heineken_unit_id, @canal_balcao, '6.00', NOW(), NOW(), NOW());

INSERT INTO products (name, categoryId, subcategory, ean, uom, minStock, currentStock, avgCost, active, isComposite, notes, createdAt, updatedAt)
VALUES 
('Heineken 269ml Pack 8un', @categoria_bebidas, 'Cerveja Premium Pack', '7891991010931', 'CX', 5, 20, '28.00', 1, 1, 'Pack com 8 unidades de Heineken 269ml', NOW(), NOW());

SET @heineken_pack_id = LAST_INSERT_ID();

INSERT INTO productPrices (productId, channelId, price, effectiveFrom, createdAt, updatedAt)
VALUES (@heineken_pack_id, @canal_balcao, '45.00', NOW(), NOW(), NOW());

INSERT INTO productCompositions (parentProductId, childProductId, quantity, createdAt)
VALUES (@heineken_pack_id, @heineken_unit_id, 8, NOW());

SELECT 'Produtos criados com sucesso!' as message;

